"""Decisive Action, Chapter 6 (Field Kit, pp100-134): the supplement's gear, built row by row.

Each show() records the item for the reconciliation report (da_report.py) and adds it to the
catalog (items.I), so it reaches equipment_catalog.md and db/seed/catalog.json like any other
item. `printed` is the CR for one item after errata; items sold per 10 print 1 CR more for the
batch (group pricing, core errata p225). Each item's errata lines come from errata_data.py.
"""
from costs import *
import items as _I
import errata_data as _E
UR='Usage Restriction'
B=[]
SOURCE='Decisive Action'
# Sold per 10 (+1 CR for the batch): charges, grenades, special rounds and missiles.
PER_10={'Agni Variable Yield Rounds','High Impact Explosive Charge','Incendiary Charge','Plasma Breaching Charge',
        'Grav Grenade','Basic STA/S Missile','Plasma STA/S Missile','Scrammer STA/S Missile','Grav STA Missile',
        'Grav Missile','Hyper Missile'}

def _errata(name):
    """The item's Decisive Action errata, as catalog errata lines."""
    out=[]
    for x in _E.E:
        if x['section']!=SOURCE: continue
        if any(item==name for item,*_ in x['changes']) or (x['subject']==name and x['kind']!='rule'):
            pg=f"p{x['p1']}"+(f"-{x['p2']}" if x['p2'] else '')
            out.append(f"(new, {x['added']}) Decisive Action {pg}: {x['text']}")
    return out

def show(name,cat,page,size,printed,rows,note=''):
    bp=sum(r[2] for r in rows); c=cr_of(size,bp)
    gap=''
    if isinstance(printed,int):
        r=[x for x in range(-600,6000) if cr_of(size,x)==printed]
        lo,hi=r[0],r[-1]
        gap='OK' if lo<=bp<=hi else (f"+{lo-bp}" if bp<lo else f"-{bp-hi}")
    B.append((name,cat,page,size,bp,c,printed,gap,note,rows))


def _register():
    """Adds every item to the catalog, grouped by section (TSA, Resistance, ...), in page order."""
    order=[TSA,RES,HAV,COV,EXP,SHO]
    for name,cat,page,size,bp,c,printed,gap,note,rows in sorted(B,key=lambda b:(order.index(b[1]),b[2])):
        per10=name in PER_10
        cr=None if printed is None else printed+(1 if per10 else 0)
        _I.item(name,cat,f"Decisive Action p{page}",size,cr,None if cr is None else cc_of(cr),rows,
                errata=_errata(name),notes=[note] if note else [],
                extra={'Sold per':'10 (+1 CR over one)'} if per10 else None)
TSA='Decisive Action: TSA'; RES='Decisive Action: Resistance'; HAV='Decisive Action: Haven & Auxiliaries'
COV='Decisive Action: Covert'; EXP='Decisive Action: Experimental'; SHO='Decisive Action: Shohan'

